macro.command:
const pass = args[0]?.macroPass;
if (pass === "preDamageRollConfig") {
  if (!workflow.activity?.hasAttack || workflow.actor.uuid !== macroItem.actor?.uuid) return;
  let state = workflow._classpackHurlThroughHell;
  if (!state) {
    if (dnd5eClasspack.resources.remaining(macroItem) < 1) return;
    const targets = [...new Set([...workflow.hitTargets, ...workflow.hitTargetsEC ?? []])].filter(t => t.actor);
    if (!targets.length) return;
    state = workflow._classpackHurlThroughHell = { checked: true };
    const userId = dnd5eClasspack.firstOwner(workflow.actor, true);
    if (!await dnd5eClasspack.dialogUtils.confirmUseItem(macroItem, { userId })) return;
    const target = targets.length === 1 ? targets[0] : (await dnd5eClasspack.dialogUtils.selectTargetDialog(
      macroItem.name, "", targets, { userId, skipDeadAndUnconscious: false }))?.[0];
    if (!target) return;
    state.targetUuid = target.document.uuid;
    state.fiend = target.actor.system.details.type?.value === "fiend";
    state.marker = `dnd5e_classpack.hurl.${foundry.utils.randomID()}`;
    await dnd5eClasspack.resources.consume([{ itemUuid: macroItem.uuid, amount: 1 }], { id: state.marker });
    state.consumed = true;
    const hooks = [];
    state.cleanup = () => {
      for (const [name, id] of hooks) Hooks.off(name, id);
      hooks.length = 0;
    };
    if (!state.fiend) {
      // Keep this damage part separate from existing psychic damage and bind it to one target.
      hooks.push(["dnd5e.preCalculateDamage", Hooks.on("dnd5e.preCalculateDamage", (_actor, damages, options) => {
        if (options.midi?.targetUuid === state.targetUuid) return;
        for (let i = damages.length - 1; i >= 0; i--) {
          if (damages[i].properties?.has(state.marker)) damages.splice(i, 1);
        }
      })]);
    }
    const finish = ended => { if (ended === workflow) state.cleanup(); };
    for (const name of ["midi-qol.postCleanup", "midi-qol.preAbort"]) hooks.push([name, Hooks.on(name, finish)]);
  }
  if (!state.consumed || state.applied || state.fiend) return;
  const config = args[0].options.config;
  config.rolls ??= [];
  if (config.rolls.some(roll => roll.options?.properties?.includes(state.marker))) return;
  config.rolls.push({
    parts: ["10d10[psychic]"], data: workflow.activity.getRollData(),
    options: { type: "psychic", types: ["psychic"], properties: ["mgc", state.marker],
      isCritical: false, configured: true, flavor: macroItem.name }
  });
  return;
}
if (pass === "postActiveEffects") {
  const state = workflow._classpackHurlThroughHell;
  if (!state?.consumed || state.applied) return;
  state.applied = true;
  state.cleanup?.();
  const token = await fromUuid(state.targetUuid);
  if (!token?.actor) return;
  const template = macroItem.effects.find(e => e.flags.dnd5e_classpack?.hurlTemplate);
  const data = template.toObject();
  delete data._id; delete data._key;
  data.origin = macroItem.uuid;
  data.system.origin = { actor: workflow.actor.uuid, item: macroItem.uuid };
  data.flags.dae.itemUuid = macroItem.uuid;
  data.flags.dae.itemData = macroItem.toObject();
  data.flags.dnd5e_classpack.hurl = {
    sourceActorUuid: workflow.actor.uuid, tokenUuid: token.uuid,
    x: token._source.x, y: token._source.y, elevation: token._source.elevation ?? 0,
    hidden: token._source.hidden ?? false
  };
  await MidiQOL.socket().executeAsGM("createEffects", { actorUuid: token.actor.uuid, effects: [data] });
  await DAE.setTokenVisibility(token.uuid, false);
  return;
}
if (pass === "preItemRoll" && workflow.actor.appliedEffects.some(e => !e.disabled && !e.isSuppressed
  && e.flags.dnd5e_classpack?.hurl)) {
  if ([...workflow.targets].some(t => t.actor?.uuid !== workflow.actor.uuid)
    || workflow.activity.target?.template?.type) return false;
  return;
}
if (args[0] !== "off") return;
const last = args.at(-1);
const state = last.efData?.flags?.dnd5e_classpack?.hurl;
if (!state) return;
const token = await fromUuid(state.tokenUuid);
if (!token?.actor) return;
const scene = token.parent;
const position = { x: state.x, y: state.y, elevation: state.elevation };
const dimensions = token.getSize(position);
const occupied = candidate => scene.tokens.some(other => {
  if (other.id === token.id || other.actor?.flags["midi-qol"]?.neverTarget) return false;
  if (other.level !== token.level || (other._source.elevation ?? 0) !== candidate.elevation) return false;
  const size = other.getSize();
  return candidate.x < other._source.x + size.width && candidate.x + dimensions.width > other._source.x
    && candidate.y < other._source.y + size.height && candidate.y + dimensions.height > other._source.y;
});
if (occupied(position)) {
  const step = scene.grid.size;
  const candidates = [];
  const columns = Math.ceil(scene.dimensions.width / step);
  const rows = Math.ceil(scene.dimensions.height / step);
  for (let x = -columns; x <= columns; x++) for (let y = -rows; y <= rows; y++) {
    const point = { x: state.x + x * step, y: state.y + y * step, elevation: state.elevation };
    if (point.x < 0 || point.y < 0 || point.x + dimensions.width > scene.dimensions.width
      || point.y + dimensions.height > scene.dimensions.height) continue;
    candidates.push({ ...point, distance: scene.grid.measurePath([position, point]).distance });
  }
  candidates.sort((a, b) => a.distance - b.distance);
  const free = candidates.find(candidate => !occupied(candidate));
  if (free) Object.assign(position, { x: free.x, y: free.y });
}
await dnd5eClasspack.socket.executeAsGM("teleportUpdate", scene.id, [{ _id: token.id, ...position }], { animate: false });
await DAE.setTokenVisibility(token.uuid, !state.hidden);
